xml.Script:
        include 'Figures\Scripts\Cube_Standard_Colors.inc';

        sColors[ 0] := '       222222              ';
        sColors[ 1] := '       200000              ';
        sColors[ 2] := '       202220              ';
        sColors[ 3] := '       200020              ';
        sColors[ 4] := '       222220              ';
        sColors[ 5] := '       000000              ';

        sColors[ 6] := '433333 055555 222222 444444';
        sColors[ 7] := '434443 050005 255555 411111';
        sColors[ 8] := '434343 050505 252225 414441';
        sColors[ 9] := '434343 050505 255525 411141';
        sColors[10] := '433343 055505 222225 444441';
        sColors[11] := '444443 000005 555555 111111';

        sColors[12] := '                     133333';
        sColors[13] := '                     131113';
        sColors[14] := '                     131313';
        sColors[15] := '                     131313';
        sColors[16] := '                     133313';
        sColors[17] := '                     111113';

        W := 0.5;
        N := 6;
        D := 2 * W / N;

        c := 0;
        for i := 0 to N do
            for j := 0 to N do
                for k := 0 to N do
                    if (i = 0) or (j = 0) or (k = 0) or (i = N) or (j = N) or (k = N) then begin
                        Vx[c] := D * i - W;
                        Vy[c] := D * j - W;
                        Vz[c] := D * k - W;
                        Idx[i,j,k] := IntToStr(c);
                        inc(c);
                    end;

        function GetSIdx(x2, y2, z2);
        begin
            Result := Idx[x2, y2, z2] + ';' + Idx[x2+dx2, y2+dy2, z2+dz2] + ';' + Idx[x2+dx1+dx2, y2+dy1+dy2, z2+dz1+dz2] + ';' + Idx[x2+dx1, y2+dy1, z2+dz1];
        end;

        function GetColor(x3, y3);
        begin
            substr := copy(sColors[y3], x3, 1);
            Result := Colors[HexToInt(substr)];
        end;

        procedure MakeSide(x, y, z, dx1, dy1, dz1, dx2, dy2, dz2, cx, cy);
        // x, y, z - left-top point of side
        // dx1, dy1, dz1 - 1st counting vector
        // dx2, dy2, dz2 - 2nd counting vector
        // cx, cy - left-top letter in sColors
        begin
            for i := 0 to N - 1 do
                for j := 0 to N - 1 do begin
                    S[c] := GetSIdx( x + dx1 * i + dx2 * j,  y + dy1 * i + dy2 * j,  z + dz1 * i + dz2 * j);
                    Cl[c] := GetColor(cx + i, cy + j);
                    Inc(c);
                end;
        end;

        c := 0;
        MakeSide( 0, N, N,  1, 0, 0,  0,-1, 0,   8, 0); // up
        MakeSide( 0, 0, N,  1, 0, 0,  0, 0,-1,   8, 6); // face
        MakeSide( 0, N, N,  0,-1, 0,  0, 0,-1,   1, 6); // left
        MakeSide( N, 0, N,  0, 1, 0,  0, 0,-1,  15, 6); // right
        MakeSide( N, N, N, -1, 0, 0,  0, 0,-1,  22, 6); // back
        MakeSide( N, N, 0, -1, 0, 0,  0,-1, 0,  22,12); // bottom
